export function FileSystemFilterBar({
  controller,
}: {
  controller: FileSystemController
}) {
  const hasFilters = fileSystemHasFilters(controller)

  if (!controller.categories.length) return null

  return (
    <div className="flex shrink-0 items-center gap-1 overflow-x-auto border-b px-2 py-1.5">
      <Filter className="size-3.5 shrink-0 text-muted-foreground" />
      {controller.categories.map((category) => {
        const isActive = controller.query.filters.categories.includes(category)

        return (
          <button
            key={category}
            type="button"
            onClick={() => controller.toggleCategory(category)}
            className={cn(
              "h-6 shrink-0 rounded-md border px-2 text-xs outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring",
              isActive
                ? "border-primary bg-primary text-primary-foreground"
                : "border-input bg-background text-muted-foreground"
            )}
          >
            {getFileSystemCategoryLabel(category)}
          </button>
        )
      })}
      {(["last7", "last30"] as const).map((preset) => {
        const isActive = controller.query.filters.updatedAfter === preset

        return (
          <button
            key={preset}
            type="button"
            onClick={() => controller.setModifiedAfter(preset)}
            className={cn(
              "h-6 shrink-0 rounded-md border px-2 text-xs outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring",
              isActive
                ? "border-primary bg-primary text-primary-foreground"
                : "border-input bg-background text-muted-foreground"
            )}
          >
            {dateModifiedFilterLabel(preset)}
          </button>
        )
      })}
      {hasFilters ? (
        <Button size="xs" variant="ghost" onClick={controller.clearFilters}>
          <X className="size-3" aria-hidden />
          Clear
        </Button>
      ) : null}
    </div>
  )
}

export function FileSystemStatusBar({
  controller,
}: {
  controller: FileSystemController
}) {
  const itemCount = controller.currentEntries.length
  const isSearching =
    normalizeFileSystemSearch(controller.query.search).length > 0
  const hasFilters = fileSystemHasFilters(controller)

  return (
    <div
      aria-live="polite"
      className="flex h-8 shrink-0 items-center justify-between gap-3 border-t bg-muted/35 px-3 text-xs text-muted-foreground"
    >
      <span>
        {itemCount}{" "}
        {isSearching || hasFilters
          ? itemCount === 1
            ? "result"
            : "results"
          : itemCount === 1
            ? "item"
            : "items"}
      </span>
      {controller.selectedEntry ? (
        <span className="min-w-0 truncate">
          {controller.selectedEntry.name} selected
        </span>
      ) : null}
    </div>
  )
}

function fileSystemHasFilters(controller: FileSystemController) {
  return (
    controller.query.filters.categories.length > 0 ||
    controller.query.filters.updatedAfter !== null
  )
}

import type * as React from "react"

export type FileSystemNavigationEntry = {
  name: string
  path: string
}

export function fileSystemEntryAtOffset<
  Entry extends FileSystemNavigationEntry,
>(entries: readonly Entry[], selectedPath: string | null, offset: number) {
  const currentIndex = entries.findIndex((entry) => entry.path === selectedPath)
  const nextIndex = Math.min(
    entries.length - 1,
    Math.max(0, currentIndex === -1 ? 0 : currentIndex + offset)
  )

  return entries[nextIndex] ?? null
}

export function fileSystemBoundaryEntry<
  Entry extends FileSystemNavigationEntry,
>(entries: readonly Entry[], boundary: "first" | "last") {
  return boundary === "first"
    ? (entries[0] ?? null)
    : (entries[entries.length - 1] ?? null)
}

export function fileSystemTypeAheadMatch<
  Entry extends FileSystemNavigationEntry,
>(
  event: React.KeyboardEvent,
  entries: readonly Entry[],
  selectedPath: string | null
) {
  if (
    event.key.length !== 1 ||
    event.altKey ||
    event.ctrlKey ||
    event.metaKey ||
    !/^[\p{L}\p{N}]$/u.test(event.key)
  ) {
    return null
  }

  const search = event.key.toLowerCase()
  const startIndex = Math.max(
    0,
    entries.findIndex((entry) => entry.path === selectedPath) + 1
  )

  for (let step = 0; step < entries.length; step += 1) {
    const entry = entries[(startIndex + step) % entries.length]

    if (entry.name.toLowerCase().startsWith(search)) {
      event.preventDefault()
      return entry
    }
  }

  return null
}

"use client"

import * as React from "react"

import {
  fileSystemBoundaryEntry,
  fileSystemEntryAtOffset,
  fileSystemTypeAheadMatch,
  type FileSystemNavigationEntry,
} from "./file-system-navigation"

export function useFileSystemRovingFocus<
  Entry extends FileSystemNavigationEntry,
>({
  entries,
  getScrollIndex,
  onSelect,
  scrollToIndex,
  selectedPath,
}: {
  entries: readonly Entry[]
  selectedPath: string | null
  onSelect: (entry: Entry) => void
  getScrollIndex?: (entry: Entry) => number
  scrollToIndex?: (index: number) => void
}) {
  const entryElements = React.useRef(new Map<string, HTMLElement>())

  const registerEntryRef = React.useCallback(
    (path: string, element: HTMLElement | null) => {
      if (element) {
        entryElements.current.set(path, element)
      } else {
        entryElements.current.delete(path)
      }
    },
    []
  )

  const focusEntry = React.useCallback(
    (entry: Entry) => {
      const index = getScrollIndex?.(entry)

      if (index !== undefined) scrollToIndex?.(index)

      requestAnimationFrame(() => {
        entryElements.current.get(entry.path)?.focus()
      })
    },
    [getScrollIndex, scrollToIndex]
  )

  const selectEntry = React.useCallback(
    (entry: Entry | null) => {
      if (!entry) return
      onSelect(entry)
      focusEntry(entry)
    },
    [focusEntry, onSelect]
  )

  const selectByOffset = React.useCallback(
    (offset: number) => {
      selectEntry(fileSystemEntryAtOffset(entries, selectedPath, offset))
    },
    [entries, selectEntry, selectedPath]
  )

  const selectBoundary = React.useCallback(
    (boundary: "first" | "last") => {
      selectEntry(fileSystemBoundaryEntry(entries, boundary))
    },
    [entries, selectEntry]
  )

  const selectTypeAhead = React.useCallback(
    (event: React.KeyboardEvent, path: string | null = selectedPath) => {
      selectEntry(fileSystemTypeAheadMatch(event, entries, path))
    },
    [entries, selectEntry, selectedPath]
  )

  return {
    focusEntry,
    registerEntryRef,
    selectBoundary,
    selectByOffset,
    selectEntry,
    selectTypeAhead,
  }
}

"use client"

import * as React from "react"

import { buildFileSystemIndex, normalizeFolderPath } from "./file-system-index"
import { deriveVisibleIndex } from "./file-system-query"
import type {
  FileSystemEntry,
  FileSystemIndex,
  FileSystemItem,
  FileSystemProps,
  FileSystemQueryState,
} from "./file-system-types"

type UseFileSystemChildrenLoaderArgs = {
  allItems: readonly FileSystemItem[]
  currentPath: string
  loadChildren: FileSystemProps["loadChildren"]
  query: FileSystemQueryState
  rawIndex: FileSystemIndex
  setLoadedItems: React.Dispatch<React.SetStateAction<FileSystemItem[]>>
  visibleIndex: FileSystemIndex
}

export function useFileSystemChildrenLoader({
  allItems,
  currentPath,
  loadChildren,
  query,
  rawIndex,
  setLoadedItems,
  visibleIndex,
}: UseFileSystemChildrenLoaderArgs) {
  const [loadingFolders, setLoadingFolders] = React.useState<Set<string>>(
    () => new Set()
  )
  const [folderErrors, setFolderErrors] = React.useState(
    new Map<string, string>()
  )
  const folderRequests = React.useRef(new Map<string, AbortController>())
  const folderPromises = React.useRef(
    new Map<string, Promise<FileSystemEntry[]>>()
  )

  React.useEffect(() => {
    const requests = folderRequests.current

    return () => {
      for (const controller of requests.values()) {
        controller.abort()
      }
    }
  }, [])

  const ensureChildren = React.useCallback(
    async (path: string, { retry = false }: { retry?: boolean } = {}) => {
      const folderPath = normalizeFolderPath(path)
      const folder = rawIndex.folders.get(folderPath)
      const rawChildren = rawIndex.children.get(folderPath) ?? []
      const currentChildren = visibleIndex.children.get(folderPath) ?? []

      if (!loadChildren || !folder?.hasChildren) return currentChildren
      if (!retry && rawChildren.length > 0) return currentChildren
      if (!retry && folderPromises.current.has(folderPath)) {
        return folderPromises.current.get(folderPath)!
      }

      const controller = new AbortController()
      const loadPromise = (async () => {
        folderRequests.current.set(folderPath, controller)
        setLoadingFolders((previous) => new Set(previous).add(folderPath))
        setFolderErrors((previous) => {
          const next = new Map(previous)

          next.delete(folderPath)
          return next
        })

        try {
          let cursor: string | null = null
          const nextItems: FileSystemItem[] = []

          do {
            const result = await loadChildren({
              cursor,
              path: folderPath,
              signal: controller.signal,
            })

            nextItems.push(...result.items)
            cursor = result.nextCursor ?? null
          } while (cursor && !controller.signal.aborted)

          if (controller.signal.aborted) return currentChildren
          if (!nextItems.length) return currentChildren

          const nextRawIndex = buildFileSystemIndex([...allItems, ...nextItems])
          const nextVisibleIndex = deriveVisibleIndex(
            nextRawIndex,
            currentPath,
            query
          )

          setLoadedItems((previous) => [...previous, ...nextItems])
          return nextVisibleIndex.children.get(folderPath) ?? []
        } catch (error) {
          if (!controller.signal.aborted) {
            setFolderErrors((previous) =>
              new Map(previous).set(folderPath, errorMessage(error))
            )
          }
          return currentChildren
        } finally {
          folderRequests.current.delete(folderPath)
          folderPromises.current.delete(folderPath)
          setLoadingFolders((previous) => {
            const next = new Set(previous)

            next.delete(folderPath)
            return next
          })
        }
      })()

      folderPromises.current.set(folderPath, loadPromise)
      return loadPromise
    },
    [
      allItems,
      currentPath,
      loadChildren,
      query,
      rawIndex.children,
      rawIndex.folders,
      setLoadedItems,
      visibleIndex.children,
    ]
  )

  return { ensureChildren, folderErrors, loadingFolders }
}

function errorMessage(error: unknown) {
  if (error instanceof Error && error.message) return error.message
  return "Couldn't load this folder."
}

