    <div className="flex max-w-xs flex-col items-center gap-2 px-6 text-center">
      {icon ? <div className="text-muted-foreground">{icon}</div> : null}
      <div className="text-sm font-medium">{title}</div>
      <div className="text-xs text-muted-foreground">{description}</div>
      {action ? <div className="pt-1">{action}</div> : null}
    </div>
  )
}

function folderInitial(name: string) {
  return name.trim().charAt(0).toUpperCase() || "/"
}

"use client"

import * as React from "react"
import {
  FileTree as PierreFileTreeModel,
  prepareFileTreeInput,
  type FileTreeDirectoryHandle,
  type FileTreeItemHandle,
  type FileTreeRowDecoration,
  type FileTreeSortComparator,
} from "@pierre/trees"
import { FileTree as PierreFileTree } from "@pierre/trees/react"

import { cn } from "@/lib/utils"

import type { FileSystemController } from "./file-system-controller"
import {
  buildFileSystemPierreListInput,
  fileSystemPathToPierrePath,
  fileSystemPierrePathToEntry,
} from "./file-system-pierre-list-adapter"
import { entryKindLabel, fileSystemFilterIsEmpty } from "./file-system-query"
import type {
  FileSystemEntry,
  FileSystemFileEntry,
  FileSystemSortKey,
} from "./file-system-types"
import { formatFileSystemSize } from "./file-system-utils"

const ROW_HEIGHT = 36
const useIsomorphicLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

export function FileSystemListView({
  controller,
  onOpenFile,
}: {
  controller: FileSystemController
  onOpenFile: (file: FileSystemFileEntry) => void
}) {
  const { currentPath, index } = controller
  const { paths, pathEntries } = React.useMemo(
    () => buildFileSystemPierreListInput(index, currentPath),
    [currentPath, index]
  )
  const expansionByCurrentPathRef = React.useRef(
    new Map<string, FileSystemPierreExpansionSnapshot>()
  )

  const hasQuery =
    controller.query.search.length > 0 ||
    !fileSystemFilterIsEmpty(controller.query.filters)
  const selectedPath = controller.selectedPath
    ? fileSystemPathToPierrePath(controller.selectedPath, currentPath)
    : null
  const selectedPaths = React.useMemo(
    () => (selectedPath && pathEntries.has(selectedPath) ? [selectedPath] : []),
    [pathEntries, selectedPath]
  )
  const getState = useLatestFileSystemListState(
    React.useMemo(
      () => ({ controller, pathEntries }),
      [controller, pathEntries]
    )
  )
  // Pierre exposes no decoration-only invalidation, so loading/error rows revise the model.
  const modelDecorationRevision = React.useMemo(
    () =>
      [
        [...controller.loadingFolders].sort().join("|"),
        [...controller.folderErrors].sort(([left], [right]) =>
          left.localeCompare(right)
        ),
      ].join("::"),
    [controller.folderErrors, controller.loadingFolders]
  )
  const pierreModelInput = React.useMemo(() => {
    const sortOrder = new Map(paths.map((path, index) => [path, index]))
    const sortByInputOrder: FileTreeSortComparator = (left, right) =>
      (sortOrder.get(left.path) ?? 0) - (sortOrder.get(right.path) ?? 0)

    return {
      hasQuery,
      modelDecorationRevision,
      paths,
      preparedInput: prepareFileTreeInput(paths, { sort: sortByInputOrder }),
      sortByInputOrder,
    }
  }, [hasQuery, modelDecorationRevision, paths])

  const model = React.useMemo(
    () =>
      new PierreFileTreeModel({
        flattenEmptyDirectories: false,
        icons: "complete",
        initialExpansion: pierreModelInput.hasQuery ? "open" : "closed",
        itemHeight: ROW_HEIGHT,
        onSelectionChange: (nextSelectedPaths) => {
          const path = nextSelectedPaths.at(-1) ?? null
          const state = getState()
          const entry = fileSystemPierrePathToEntry(path, state.pathEntries)

          state.controller.selectEntry(entry)
          if (entry?.kind === "folder") {
            void state.controller.ensureChildren(entry.path)
          }
        },
        overscan: 12,
        preparedInput: pierreModelInput.preparedInput,
        renderRowDecoration: ({ item }) => {
          const state = getState()
          const entry = fileSystemPierrePathToEntry(
            item.path,
            state.pathEntries
          )

          return entry ? fileSystemRowDecoration(entry, state.controller) : null
        },
        search: false,
        sort: pierreModelInput.sortByInputOrder,
        stickyFolders: false,
        unsafeCSS: FILE_TREE_CSS,
      }),
    [getState, pierreModelInput]
  )

  useIsomorphicLayoutEffect(() => {
    if (hasQuery) return

    const snapshot = expansionByCurrentPathRef.current.get(currentPath)

    if (snapshot && !snapshot.wasQueryActive) {
      restoreOpenPierrePaths(model, snapshot.openPaths)
    }
  }, [currentPath, hasQuery, model])
  React.useEffect(
    () => () => {
      const openPaths = collectOpenPierrePaths(model, paths)
      const previousSnapshot =
        expansionByCurrentPathRef.current.get(currentPath)

      if (!hasQuery || !previousSnapshot || previousSnapshot.wasQueryActive) {
        expansionByCurrentPathRef.current.set(currentPath, {
          openPaths,
          wasQueryActive: hasQuery,
        })
      }
      model.cleanUp()
    },
    [currentPath, hasQuery, model, paths]
  )
  React.useEffect(() => {
    const selectedPathSet = new Set(selectedPaths)

    for (const path of model.getSelectedPaths()) {
      if (!selectedPathSet.has(path)) model.getItem(path)?.deselect()
    }
    for (const path of selectedPaths) {
      if (!model.getSelectedPaths().includes(path)) {
        model.getItem(path)?.select()
      }
    }
  }, [model, selectedPaths])

  const openPierrePath = React.useCallback((path: string | null) => {
    if (!path) return
    const entry = fileSystemPierrePathToEntry(path, pathEntries)

    if (!entry) return
    if (entry.kind === "folder") {
      if (controller.folderErrors.has(entry.path)) {
        void controller.ensureChildren(entry.path, { retry: true })
      }
      controller.navigateTo(entry.path)
      return
    }

    onOpenFile(entry)
  }, [controller, onOpenFile, pathEntries])

  const handleDoubleClick = React.useCallback(
    (event: React.MouseEvent<HTMLElement>) => {
      openPierrePath(pierrePathFromEvent(event))
    },
    [openPierrePath]
  )

  const handleKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLElement>) => {
      if (event.key !== "Enter") return

      openPierrePath(
        model.getFocusedPath() ?? model.getSelectedPaths().at(-1) ?? null
      )
      event.preventDefault()
    },
    [model, openPierrePath]
  )

  if (!paths.length) {
    return <FileSystemEmptyRows label="This folder is empty" />
  }

  return (
    <div className="flex size-full flex-col">
      <div className="flex h-9 shrink-0 items-center gap-3 overflow-x-auto border-b bg-muted/30 px-3 text-xs font-medium text-muted-foreground">
        <SortHeader controller={controller} label="Name" sortKey="name" />
        <SortHeader controller={controller} label="Type" sortKey="kind" />
        <SortHeader controller={controller} label="Size" sortKey="size" />
        <SortHeader
          controller={controller}
          label="Modified"
          sortKey="updatedAt"
        />
      </div>
      <div className="min-h-0 flex-1">
        <PierreFileTree
          aria-label="Files"
          className="block size-full"
          data-slot="file-system-pierre-tree"
          model={model}
          onDoubleClick={handleDoubleClick}
          onKeyDown={handleKeyDown}
        />
      </div>
    </div>
  )
}

type FileSystemListState = {
  controller: FileSystemController
  pathEntries: Map<string, FileSystemEntry>
}

type FileSystemPierreExpansionSnapshot = {
  openPaths: string[]
  wasQueryActive: boolean
}

function useLatestFileSystemListState(state: FileSystemListState) {
  const stateRef = React.useRef(state)

  useIsomorphicLayoutEffect(() => {
    stateRef.current = state
  }, [state])

  return React.useCallback(() => stateRef.current, [])
}

function pierrePathFromEvent(event: React.SyntheticEvent<HTMLElement>) {
  for (const target of event.nativeEvent.composedPath()) {
    if (
      target instanceof HTMLElement &&
      target.dataset.type === "item" &&
      target.dataset.itemPath
    ) {
      return target.dataset.itemPath
    }
  }

  return null
}

function collectOpenPierrePaths(
  model: PierreFileTreeModel,
  paths: readonly string[]
) {
  return paths.filter((path) => {
    const item = model.getItem(path)

    return isPierreDirectoryItem(item) && item.isExpanded()
  })
}

function restoreOpenPierrePaths(
  model: PierreFileTreeModel,
  openPaths: readonly string[]
) {
  for (const path of openPaths) {
    const item = model.getItem(path)

    if (isPierreDirectoryItem(item) && !item.isExpanded()) item.expand()
  }
}

function isPierreDirectoryItem(
  item: FileTreeItemHandle | null
): item is FileTreeDirectoryHandle {
  return item?.isDirectory() === true
}

function fileSystemRowDecoration(
  entry: FileSystemEntry,
  controller: FileSystemController
): FileTreeRowDecoration {
  if (entry.kind === "folder") {
    const loading = controller.loadingFolders.has(entry.path)
    const error = controller.folderErrors.get(entry.path)

    if (loading) return { text: "Loading" }
    if (error) return { text: error, title: error }
    return { text: "Folder" }
  }

  const size = formatFileSystemSize(entry.size)
  const type = entryKindLabel(entry)

  return { text: size ? `${type} · ${size}` : type }
}

function SortHeader({
  controller,
  label,
  sortKey,
}: {
  controller: FileSystemController
  label: string
  sortKey: FileSystemSortKey
}) {
  const isActive = controller.query.sort.key === sortKey

  return (
    <button
      type="button"
      className={cn(
        "flex items-center gap-1 text-left outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring",
        isActive && "text-foreground"
      )}
      onClick={() => controller.setSortKey(sortKey)}
    >
      {label}
      {isActive ? (
        <span aria-hidden>
          {controller.query.sort.direction === "asc" ? "↑" : "↓"}
        </span>
      ) : null}
    </button>
  )
}

export function FileSystemEmptyRows({ label }: { label: string }) {
  return (
    <div className="flex size-full items-center justify-center text-sm text-muted-foreground">
      {label}
    </div>
  )
}

const FILE_TREE_CSS = `
  :host {
    --trees-bg-override: transparent;
    --trees-fg-override: var(--foreground);
    --trees-fg-muted-override: var(--muted-foreground);
    --trees-bg-muted-override: var(--accent);
    --trees-border-color-override: transparent;
    --trees-focus-ring-color-override: var(--ring);
    --trees-selected-bg-override: var(--primary);
    --trees-selected-fg-override: var(--primary-foreground);
    --trees-font-family-override: inherit;
    --trees-font-size-override: 0.875rem;
    --trees-item-height: ${ROW_HEIGHT}px;
    --trees-item-padding-x-override: 0.75rem;
    --trees-item-margin-x-override: 0;
    --trees-padding-inline-override: 0;
    --trees-border-radius-override: 0;
  }
`

"use client"

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"
import { Folder } from "lucide-react"

import { cn } from "@/lib/utils"
import { ScrollArea } from "@/components/ui/scroll-area"

import type { FileSystemController } from "./file-system-controller"
import { FileSystemThumbnail } from "./file-system-preview"
import type { FileSystemEntry, FileSystemFileEntry } from "./file-system-types"
import { useFileSystemRovingFocus } from "./use-file-system-roving-focus"

const TILE_MIN_WIDTH = 124
const TILE_HEIGHT = 132
const GRID_PADDING = 12

export function FileSystemGridView({
  controller,
  onOpenFile,
}: {
  controller: FileSystemController
  onOpenFile: (file: FileSystemFileEntry) => void
}) {
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const [columnCount, setColumnCount] = React.useState(1)
  const entries = controller.currentEntries

  React.useLayoutEffect(() => {
    const viewport = viewportRef.current
    if (!viewport || typeof ResizeObserver === "undefined") return

    const update = () => {
      const available = Math.max(1, viewport.clientWidth - GRID_PADDING * 2)
      setColumnCount(Math.max(1, Math.floor(available / TILE_MIN_WIDTH)))
    }
    const observer = new ResizeObserver(update)

    update()
    observer.observe(viewport)
    return () => observer.disconnect()
  }, [])

  const rowCount = Math.ceil(entries.length / columnCount)
  const virtualizer = useVirtualizer({
    count: rowCount,
    estimateSize: () => TILE_HEIGHT,
    getScrollElement: () => viewportRef.current,
    overscan: 5,
  })
  const virtualRows = virtualizer.getVirtualItems()
  const renderedRows = virtualRows.length
    ? virtualRows.map((row) => ({ index: row.index, start: row.start }))
    : Array.from({ length: rowCount }, (_, index) => ({
        index,
        start: index * TILE_HEIGHT,
      }))
  const totalSize = virtualRows.length
    ? virtualizer.getTotalSize()
    : rowCount * TILE_HEIGHT
  const rovingFocus = useFileSystemRovingFocus({
    entries,
    getScrollIndex: (entry) => {
      const index = entries.findIndex(
        (candidate) => candidate.path === entry.path
      )

      return index === -1 ? -1 : Math.floor(index / columnCount)
    },
    onSelect: controller.selectEntry,
    scrollToIndex: (index) => {
      if (index !== -1) virtualizer.scrollToIndex(index)
    },
    selectedPath: controller.selectedPath,
  })
  const openEntry = React.useCallback(
    (entry: FileSystemEntry) => {
      if (entry.kind === "folder") {
        controller.navigateTo(entry.path)
      } else {
        onOpenFile(entry)
      }
    },
    [controller, onOpenFile]
  )
  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
      rovingFocus.selectByOffset(event.key === "ArrowRight" ? 1 : -1)
      event.preventDefault()
      return
    }
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      rovingFocus.selectByOffset(
        event.key === "ArrowDown" ? columnCount : -columnCount
      )
      event.preventDefault()
      return
    }
    if (event.key === "Home" || event.key === "End") {
      rovingFocus.selectBoundary(event.key === "Home" ? "first" : "last")
      event.preventDefault()
      return
    }
    if (event.key === "Enter" && controller.selectedEntry) {
      openEntry(controller.selectedEntry)
      event.preventDefault()
      return
    }

    rovingFocus.selectTypeAhead(event)
  }

  if (!entries.length) {
    return (
      <div className="flex size-full items-center justify-center text-sm text-muted-foreground">
        This folder is empty
      </div>
    )
  }

  return (
    <ScrollArea
      orientation="vertical"
      viewportRef={viewportRef}
      viewportClassName="p-3"
      viewportProps={{
        onKeyDown: handleKeyDown,
        role: "listbox",
        tabIndex: 0,
        "aria-label": "Files",
      }}
    >
      <div className="relative" style={{ height: totalSize }}>
        {renderedRows.map((row) => {
          const rowEntries = entries.slice(
            row.index * columnCount,
            row.index * columnCount + columnCount
          )

          return (
            <div
              key={row.index}
              className="absolute inset-x-0 grid gap-2"
              style={{
                gridTemplateColumns: `repeat(${columnCount}, minmax(0, 1fr))`,
                transform: `translateY(${row.start}px)`,
              }}
            >
              {rowEntries.map((entry) => (
                <FileSystemGridTile
                  key={entry.path}
                  controller={controller}
                  entry={entry}
                  onOpenFile={onOpenFile}
                  ref={(element) => {
                    rovingFocus.registerEntryRef(entry.path, element)
                  }}
                />
              ))}
            </div>
          )
        })}
      </div>
    </ScrollArea>
  )
}

const FileSystemGridTile = React.forwardRef<
  HTMLButtonElement,
  {
    controller: FileSystemController
    entry: FileSystemEntry
    onOpenFile: (file: FileSystemFileEntry) => void
  }
>(function FileSystemGridTile({ controller, entry, onOpenFile }, ref) {
  const isSelected = entry.path === controller.selectedPath

  return (
    <button
      ref={ref}
      type="button"
      role="option"
      aria-selected={isSelected}
      tabIndex={isSelected || !controller.selectedPath ? 0 : -1}
      onClick={() => controller.selectEntry(entry)}
      onDoubleClick={() => {
        if (entry.kind === "folder") {
          controller.navigateTo(entry.path)
        } else {
          onOpenFile(entry)
        }
      }}
      className="group flex h-[124px] min-w-0 flex-col items-center gap-2 rounded-md p-2 text-center outline-none hover:bg-accent/50 focus-visible:ring-2 focus-visible:ring-ring"
    >
      <span
        className={cn(
          "flex size-16 shrink-0 items-center justify-center rounded-md",
          isSelected && "bg-accent"
        )}
      >
        {entry.kind === "folder" ? (
          <Folder className="size-11 text-sky-500" aria-hidden />
        ) : (
          <FileSystemThumbnail
            file={entry}
            resolveFileSource={controller.resolveFileSource}
            className="w-14"
          />
        )}
      </span>
      <span
        className={cn(
          "line-clamp-2 max-w-full rounded px-1 text-xs leading-tight break-words",
          isSelected && "bg-primary text-primary-foreground"
        )}
      >
        {entry.name}
      </span>
    </button>
  )
})

"use client"

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"
import { ChevronRight, Folder } from "lucide-react"

import { cn } from "@/lib/utils"
import { ScrollArea } from "@/components/ui/scroll-area"

import type { FileSystemController } from "./file-system-controller"
import { folderHasChildren, pathParent } from "./file-system-index"
import { FileSystemThumbnail } from "./file-system-preview"
import type { FileSystemEntry, FileSystemFileEntry } from "./file-system-types"
import { useFileSystemRovingFocus } from "./use-file-system-roving-focus"

const COLUMN_ROW_HEIGHT = 32

export function FileSystemColumnsView({
  controller,
  onOpenFile,
}: {
  controller: FileSystemController
  onOpenFile: (file: FileSystemFileEntry) => void
}) {
  const columnPaths = React.useMemo(() => {
    const paths = [controller.currentPath]
    const selectedPath = controller.selectedPath

    if (!selectedPath?.startsWith(controller.currentPath)) return paths

    const selectedEntry = controller.selectedEntry
    const targetPath =
      selectedEntry?.kind === "folder"
        ? selectedEntry.path
        : (selectedEntry?.parentPath ?? controller.currentPath)
    const relativePath = targetPath.slice(controller.currentPath.length)
    let walkedPath = controller.currentPath

    for (const segment of relativePath.split("/")) {
      if (!segment) continue
      walkedPath = `${walkedPath}${segment}/`
      paths.push(walkedPath)
    }

    return paths
  }, [
    controller.currentPath,
    controller.selectedEntry,
    controller.selectedPath,
  ])

  return (
    <ScrollArea
      orientation="horizontal"
      viewportClassName="overscroll-x-contain"
    >
      <div className="flex h-full min-w-full">
        {columnPaths.map((path, index) => (
          <FileSystemColumn
            key={path || "(root)"}
            controller={controller}
            isLast={index === columnPaths.length - 1}
            onOpenFile={onOpenFile}
            path={path}
          />
        ))}
      </div>
    </ScrollArea>
  )
}

function FileSystemColumn({
  controller,
  isLast,
  onOpenFile,
  path,
}: {
  controller: FileSystemController
  isLast: boolean
  onOpenFile: (file: FileSystemFileEntry) => void
  path: string
}) {
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const entries = React.useMemo(
    () => controller.index.children.get(path) ?? [],
    [controller.index.children, path]
  )
  const virtualizer = useVirtualizer({
    count: entries.length,
    estimateSize: () => COLUMN_ROW_HEIGHT,
    getScrollElement: () => viewportRef.current,
    overscan: 10,
  })
  const virtualRows = virtualizer.getVirtualItems()
  const renderedRows = virtualRows.length
    ? virtualRows.map((row) => ({
        entry: entries[row.index],
        start: row.start,
      }))
    : entries.map((entry, index) => ({
        entry,
        start: index * COLUMN_ROW_HEIGHT,
      }))
  const totalSize = virtualRows.length
    ? virtualizer.getTotalSize()
    : entries.length * COLUMN_ROW_HEIGHT
  const rovingFocus = useFileSystemRovingFocus({
    entries,
    getScrollIndex: (entry) =>
      entries.findIndex((candidate) => candidate.path === entry.path),
    onSelect: (entry) => {
      controller.selectEntry(entry)
      if (entry.kind === "folder") void controller.ensureChildren(entry.path)
    },
    scrollToIndex: (index) => {
      if (index !== -1) virtualizer.scrollToIndex(index)
    },
    selectedPath: controller.selectedPath,
  })
  const openEntry = React.useCallback(
    (entry: FileSystemEntry) => {
      if (entry.kind === "folder") {
        controller.navigateTo(entry.path)
      } else {
        onOpenFile(entry)
      }
    },
    [controller, onOpenFile]
  )
  const selectParent = React.useCallback(() => {
    const selectedEntry = controller.selectedEntry
    if (!selectedEntry) return

    const parentPath =
      selectedEntry.kind === "folder"
        ? pathParent(selectedEntry.path)
        : selectedEntry.parentPath
    const parent = parentPath
      ? (controller.rawIndex.folders.get(parentPath) ?? null)
      : null

    if (parent) controller.selectEntry(parent)
  }, [controller])
  const selectChild = React.useCallback(() => {
    const selectedEntry = controller.selectedEntry
    if (selectedEntry?.kind !== "folder") return

    void controller.selectFirstChildAfterEnsure(selectedEntry.path)
  }, [controller])
  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      rovingFocus.selectByOffset(event.key === "ArrowDown" ? 1 : -1)
      event.preventDefault()
      return
    }
    if (event.key === "Home" || event.key === "End") {
      rovingFocus.selectBoundary(event.key === "Home" ? "first" : "last")
      event.preventDefault()
      return
    }
    if (event.key === "ArrowRight") {
      selectChild()
      event.preventDefault()
      return
    }
    if (event.key === "ArrowLeft") {
      selectParent()
      event.preventDefault()
      return
    }
    if (event.key === "Enter" && controller.selectedEntry) {
      openEntry(controller.selectedEntry)
      event.preventDefault()
      return
    }

    rovingFocus.selectTypeAhead(event)
  }

  return (
    <div
      className={cn("w-64 shrink-0 border-r", isLast && "flex-1")}
      role="listbox"
      aria-label={path || "Files"}
      tabIndex={0}
      onKeyDown={handleKeyDown}
    >
      <div ref={viewportRef} className="h-full overflow-auto p-1.5">
        {entries.length ? (
          <div className="relative" style={{ height: totalSize }}>
            {renderedRows.map(({ entry, start }) => (
              <FileSystemColumnRow
                key={entry.path}
                controller={controller}
                entry={entry}
                onOpenFile={onOpenFile}
                ref={(element) => {
                  rovingFocus.registerEntryRef(entry.path, element)
                }}
                style={{ transform: `translateY(${start}px)` }}
              />
            ))}
          </div>
        ) : (
          <div className="px-2 py-1.5 text-xs text-muted-foreground">
            This folder is empty
          </div>
        )}
      </div>
    </div>
  )
}

const FileSystemColumnRow = React.forwardRef<
  HTMLButtonElement,
  {
    controller: FileSystemController
    entry: FileSystemEntry
    onOpenFile: (file: FileSystemFileEntry) => void
    style: React.CSSProperties
  }
>(function FileSystemColumnRow({ controller, entry, onOpenFile, style }, ref) {
  const isSelected = entry.path === controller.selectedPath
  const isOnTrail =
    entry.kind === "folder" &&
    controller.selectedPath?.startsWith(entry.path) &&
    pathParent(controller.selectedPath) !== entry.parentPath

  return (
    <button
      ref={ref}
      type="button"
      role="option"
      aria-selected={isSelected}
      tabIndex={isSelected || !controller.selectedPath ? 0 : -1}
      onClick={() => {
        controller.selectEntry(entry)
        if (entry.kind === "folder") void controller.ensureChildren(entry.path)
      }}
      onDoubleClick={() => {
        if (entry.kind === "folder") {
          controller.navigateTo(entry.path)
        } else {
          onOpenFile(entry)
        }
      }}
      className={cn(
        "absolute inset-x-0 flex h-8 shrink-0 items-center gap-2 rounded-md px-2 text-left text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring",
        isSelected
          ? "bg-primary text-primary-foreground"
          : isOnTrail
            ? "bg-accent"
            : "hover:bg-accent/50"
      )}
      style={style}
    >
      {entry.kind === "folder" ? (
        <Folder className="size-4 shrink-0 text-sky-500" aria-hidden />
      ) : (
        <FileSystemThumbnail
          file={entry}
          resolveFileSource={controller.resolveFileSource}
          className="w-4 shrink-0"
        />
      )}
      <span className="min-w-0 flex-1 truncate">{entry.name}</span>
      {entry.kind === "folder" &&
      folderHasChildren(controller.rawIndex, entry) ? (
        <ChevronRight className="size-3.5 shrink-0 text-muted-foreground" />
      ) : null}
    </button>
  )
})

"use client"

import * as React from "react"
import { Folder } from "lucide-react"

import { cn } from "@/lib/utils"
import { ScrollArea } from "@/components/ui/scroll-area"

import type { FileSystemController } from "./file-system-controller"
import { FileSystemPreview, FileSystemThumbnail } from "./file-system-preview"
import type {
  FileSystemEntry,
  FileSystemFileEntry,
  FileSystemFileItem,
} from "./file-system-types"
import { useFileSystemRovingFocus } from "./use-file-system-roving-focus"

export function FileSystemGalleryView({
  controller,
  onOpenFile,
  renderFileActions,
  renderMetadata,
}: {
  controller: FileSystemController
  onOpenFile: (file: FileSystemFileEntry) => void
  renderFileActions?: (file: FileSystemFileItem) => React.ReactNode
  renderMetadata?: (item: FileSystemEntry) => React.ReactNode
}) {
  const activeEntry =
    controller.selectedEntry ?? controller.currentEntries[0] ?? null

  React.useEffect(() => {
    if (!controller.selectedEntry && activeEntry) {
      controller.selectEntry(activeEntry)
    }
  }, [activeEntry, controller])
  const rovingFocus = useFileSystemRovingFocus({
    entries: controller.currentEntries,
    onSelect: controller.selectEntry,
    selectedPath: activeEntry?.path ?? controller.selectedPath,
  })
  const openEntry = React.useCallback(
    (entry: FileSystemEntry) => {
      if (entry.kind === "folder") {
        controller.navigateTo(entry.path)
      } else {
        onOpenFile(entry)
      }
    },
    [controller, onOpenFile]
  )
  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "ArrowRight" || event.key === "ArrowDown") {
      rovingFocus.selectByOffset(1)
      event.preventDefault()
      return
    }
    if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
      rovingFocus.selectByOffset(-1)
      event.preventDefault()
      return
    }
    if (event.key === "Home" || event.key === "End") {
      rovingFocus.selectBoundary(event.key === "Home" ? "first" : "last")
      event.preventDefault()
      return
    }
    if (event.key === "Enter" && activeEntry) {
      openEntry(activeEntry)
      event.preventDefault()
      return
    }

    rovingFocus.selectTypeAhead(
      event,
      activeEntry?.path ?? controller.selectedPath
    )
  }

  return (
    <div className="flex size-full flex-col">
      <div className="min-h-0 flex-1">
        <FileSystemPreview
          entry={activeEntry}
          renderFileActions={renderFileActions}
          renderMetadata={renderMetadata}
          resolveFileSource={controller.resolveFileSource}
          className="size-full border-l-0"
        />
      </div>
      <ScrollArea
        orientation="horizontal"
        className="h-[74px] shrink-0 border-t"
        viewportClassName="p-2"
      >
        <div
          className="flex h-14 items-center gap-1.5"
          role="listbox"
          aria-label="Files"
          tabIndex={0}
          onKeyDown={handleKeyDown}
        >
          {controller.currentEntries.map((entry) => (
            <button
              ref={(element) => {
                rovingFocus.registerEntryRef(entry.path, element)
              }}
              key={entry.path}
              type="button"
              role="option"
              aria-label={entry.name}
              aria-selected={entry.path === activeEntry?.path}
              tabIndex={entry.path === activeEntry?.path ? 0 : -1}
              onClick={() => controller.selectEntry(entry)}
              onDoubleClick={() => {
                if (entry.kind === "folder") {
                  controller.navigateTo(entry.path)
                } else {
                  onOpenFile(entry)
                }
              }}
              className={cn(
                "flex size-14 shrink-0 items-center justify-center rounded-md border border-transparent p-1 outline-none focus-visible:ring-2 focus-visible:ring-ring",
                entry.path === activeEntry?.path && "border-ring/40 bg-accent"
              )}
            >
              {entry.kind === "folder" ? (
                <Folder className="size-9 text-sky-500" aria-hidden />
              ) : (
                <FileSystemThumbnail
                  file={entry}
                  resolveFileSource={controller.resolveFileSource}
                  className="w-10"
                />
              )}
            </button>
          ))}
        </div>
      </ScrollArea>
    </div>
  )
}

import { formatFileSize } from "@/components/ui/file-size-format"

export function formatFileSystemSize(size: number | undefined) {
  return typeof size === "number" ? formatFileSize(size) : ""
}

export function formatFileSystemDate(value: string | undefined) {
  if (!value) return ""

  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return ""

  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date)
}
